(function () {
  'use strict';
  const A = window.A, e = A.esc;
  // Resolve the current context even after role changes or demo reset.
  const c = new Proxy({}, {get:(_,key)=>A.context[key],set:(_,key,value)=>{A.context[key]=value;return true;}});
  const field = (label, name, attrs = '', value = '', hint = '') => `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" ${attrs} value="${e(value)}">${hint ? `<small>${hint}</small>` : ''}</div>`;
  const select = (label, name, options, value) => `<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}" ${name==='category'?'required':''}>${options.map(([v,t])=>`<option value="${e(v)}" ${v===value?'selected':''}>${e(t)}</option>`).join('')}</select></div>`;
  const area = (label, name, value = '', hint = '', required = true) => `<div class="field full"><label for="${name}">${label}</label><textarea id="${name}" name="${name}" ${required ? 'required' : ''} maxlength="3000">${e(value)}</textarea>${hint ? `<small>${hint}</small>` : ''}</div>`;
  const err = '<p class="error" id="flow-error" role="alert" aria-live="polite"></p>';
  function fail(text) { const node = document.getElementById('flow-error'); if (node) node.textContent = text; else A.toast(text); }
  function values(form) { return Object.fromEntries(new FormData(form).entries()); }
  function validGithub(value, profile = false) { try { const u = new URL(value); return u.protocol === 'https:' && u.hostname === 'github.com' && !u.search && !u.hash && !u.username && !u.password && (profile ? /^\/[A-Za-z0-9](?:[A-Za-z0-9-]{0,38})\/?$/ : /^\/[A-Za-z0-9][A-Za-z0-9-]{0,38}\/[A-Za-z0-9_.-]+\/?$/).test(u.pathname); } catch { return false; } }
  function normalizeRepo(value) { return value.trim().replace(/\/$/, '').replace(/\.git$/, ''); }
  function pageHeading(title, desc) { return `<div class="page-heading"><div class="heading-copy"><div class="eyebrow">Antislop workspace</div><h1>${title}</h1><p>${desc}</p></div></div>`; }
  function authFrame(content) {
    return `<div class="auth-layout"><aside class="auth-brand"><div class="logo"><span class="logo-mark">${A.icon('shield')}</span>antislop</div><h1>Better code.<br>Greater confidence.</h1><p>Bring your code and your expertise together. A clear path from first review to a verified fix.</p><div class="hero-art"><div class="orbit"></div><div class="orbit two"></div><div class="code-float"><div class="dots"><i></i><i></i><i></i></div><div class="code-line"></div><div class="code-line"></div><div class="code-line"></div><div class="code-line"></div></div><div class="shield-float">${A.icon('shield')}</div><span class="spark">✧</span></div><footer>Trust grows from evidence. Build with confidence.</footer></aside><section class="auth-form">${content}</section></div>`;
  }
  function finishRegistration() {
    const d = c.registration || {name:'Demo member',email:'member@example.com',role:c.authRole || 'submitter'};
    A.state.user = {name:d.name,email:d.email}; A.state.role = d.role;
    A.state.application = A.state.applications.find(x=>x.email.toLowerCase()===d.email.toLowerCase()) || null;
    c.applicationDraft=null;c.verificationEditing=false;
    A.persist(); A.closeModal(); A.go(d.role === 'coder' ? 'verification' : 'overview');
    A.toast('Local demo account created. No live authentication was performed.');
  }
  A.views.register = () => {
    const d = c.registration || {}, role = c.authRole || d.role || 'submitter';
    return authFrame(`<div class="eyebrow">Your next step starts here</div><h1>Join Antislop</h1><p>Choose how you want to work. You can explore both dashboards in this prototype.</p><div class="role-cards"><button type="button" class="role-card ${role==='submitter'?'active':''}" data-action="auth-role" data-role="submitter" aria-pressed="${role==='submitter'}">${A.icon('folder')}<strong>I have code to review</strong><small>Submit a repository and work with expert reviewers.</small></button><button type="button" class="role-card ${role==='coder'?'active':''}" data-action="auth-role" data-role="coder" aria-pressed="${role==='coder'}">${A.icon('code')}<strong>I’m a coder / doer</strong><small>Verify your experience and take on review work.</small></button></div><form data-form="register">${field('Full name','name','required autocomplete="name" maxlength="100"',d.name||'')}${field('Email address','email','type="email" required autocomplete="email" maxlength="254"',d.email||'')}${err}<label class="check-label"><input type="checkbox" name="demoConsent" required> I understand this creates a local prototype profile. I’ll use sample details and no sensitive information.</label><button class="btn primary" type="submit">Continue with email ${A.icon('arrow')}</button></form><div class="or">or</div>${A.btn('<span class="google-icon" aria-hidden="true">G</span> Continue with Google','google-login','secondary')}<p class="auth-foot">Email OTP and Google SSO are UI demonstrations. Live providers are not connected.</p><p class="auth-foot"><button data-action="go" data-route="landing">Back to home</button></p>`);
  };
  A.views.otp = () => authFrame(`<div class="eyebrow">Email verification · demo</div><h1>Check your email flow</h1><p>Complete the prototype verification for <strong>${e(c.registration?.email || 'your email')}</strong>.</p><div class="notice amber">${A.icon('mail')}<span>No email has been sent. Use demo code <strong>482913</strong>. This code verifies only the local prototype flow.</span></div><form data-form="otp">${field('6-digit verification code','otp','required inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" class="otp-input"','','Enter the displayed demo code. No real inbox verification occurs.')}${err}<button type="submit" class="btn primary">Verify demo account ${A.icon('check')}</button></form><p class="auth-foot"><button data-action="demo-resend">Show demo code again</button> · <button data-action="go" data-route="register">Change email</button></p>`);
  A.actions['auth-role'] = el => { c.authRole = el.dataset.role === 'coder' ? 'coder' : 'submitter'; const form = document.querySelector('[data-form="register"]'); if (form) c.registration = {...values(form),role:c.authRole}; A.render(); };
  A.forms.register = form => { const d = values(form); if(!d.name.trim()) return fail('Please enter your name.'); c.registration = {name:d.name.trim(),email:d.email.trim(),role:c.authRole || c.registration?.role || 'submitter'}; A.go('otp'); };
  A.forms.otp = form => { if(values(form).otp !== '482913') return fail('Enter 482913 to continue with the demo.'); finishRegistration(); };
  A.actions['demo-resend'] = () => A.toast('Demo code: 482913. No email was sent.');
  A.actions['google-login'] = () => {
    const form = document.querySelector('[data-form="register"]');
    if(form) { const v=values(form); c.registration={name:v.name.trim() || 'Demo member',email:v.email.trim() || 'member@example.com',role:c.authRole || 'submitter'}; }
    A.modal('Google sign-in needs configuration','The Google authentication experience is included in this prototype.',`<div class="notice amber">${A.icon('lock')}<span>Google OAuth is not connected. A real integration requires a registered client, verified redirect URLs, and a secure server session. No Google account has been accessed.</span></div><p class="muted">You can continue with a local demo profile to explore your selected dashboard.</p><div class="form-actions">${A.btn('Cancel','close-modal','secondary')}${A.btn('Continue with demo profile','google-demo')}</div>`);
  };
  A.actions['google-demo'] = finishRegistration;
  A.actions.go = el => A.go(el.dataset.route === 'landing' ? 'home' : el.dataset.route);

  function draft() { return c.reviewDraft ||= {title:'',repo:'',category:'general',revisionType:'commit',revision:'',stack:'TypeScript / Node.js',scope:'',budget:'',deadline:'',visibility:'private'}; }
  A.views['new-review'] = () => {
    const d=draft(), step=c.reviewStep || 1;
    let content='';
    if(step===1) content=`<div class="section-title"><h2>Start with your repository</h2><p>Tell us what to review and pin the code revision.</p></div><div class="form-grid">${field('Review title','title','required maxlength="100" placeholder="e.g. Verify our checkout flow"',d.title)}${select('Task category','category',A.categories.map(x=>[x.id,x.label]),A.category(d.category).id)}${select('Primary stack','stack',[['TypeScript / Node.js','TypeScript / Node.js'],['Python','Python'],['Go','Go'],['Java','Java'],['Other','Other']],d.stack)}<div class="field full"><label for="repo">GitHub repository URL</label><input id="repo" name="repo" type="url" required placeholder="https://github.com/your-org/your-repo" value="${e(d.repo)}"><small>Use a repository link. Access is arranged in the next stage.</small></div>${select('Review revision','revisionType',[['commit','Commit SHA'],['pull-request','Pull request number']],d.revisionType)}${field('Commit SHA or PR number','revision','required maxlength="40" placeholder="a1b2c3d or 42"',d.revision,'A commit SHA is 7–40 hexadecimal characters. A PR number is a positive integer.')}${select('Repository visibility','visibility',[['private','Private repository'],['public','Public repository']],d.visibility)}</div><div class="notice">${A.icon('lock')}<span>Never submit repository tokens, passwords, or secrets. For private code, the access workflow will show <strong>antislop@bee3.in</strong>.</span></div>`;
    if(step===2) content=`<div class="section-title"><h2>Make the review meaningful</h2><p>Clear expectations help the AI and your expert focus on what matters.</p></div><div class="form-grid">${area('Review brief and acceptance criteria','scope',d.scope,'Describe important workflows, known concerns, and what a successful review looks like.')}${field('Expert review budget (USD)','budget','type="number" required min="1" max="1000000" step="1" placeholder="750"',d.budget,'Illustrative budget only. Payments are not connected.')}${field('Preferred turnaround date','deadline','type="date" required',d.deadline,'Your requested date; an expert must agree to the schedule.')}</div><div class="notice">${A.icon('shield')}<span>Start with AI review, then select a verified doer. Repository access for the AI and for your selected doer is tracked separately.</span></div>`;
    if(step===3) content=`<div class="section-title"><h2>Ready for the next step</h2><p>Review your brief before creating a local demo request.</p></div><div class="kv"><span>Review</span><strong>${e(d.title)}</strong></div><div class="kv"><span>Task category</span>${A.categoryBadge(d)}</div><div class="kv"><span>Repository</span><span>${e(d.repo)}</span></div><div class="kv"><span>${d.revisionType==='commit'?'Commit SHA':'Pull request'}</span><span>${e(d.revision)}</span></div><div class="kv"><span>Stack / visibility</span><span>${e(d.stack)} · ${e(d.visibility)}</span></div><div class="kv"><span>Budget / preferred date</span><span>$${e(d.budget)} · ${e(d.deadline)}</span></div><h3 style="margin:20px 0 8px">Review brief</h3><p style="white-space:pre-wrap;overflow-wrap:anywhere">${e(d.scope)}</p><div class="notice amber">${A.icon('git')}<span>This prototype stores the request locally. No repository is fetched and no AI scan starts. If you use a PR number, the live integration must resolve and pin its exact commit before a scan.</span></div><label class="check-label"><input type="checkbox" name="authorized" required>I am authorized to request review of this repository and share its access.</label>`;
    return `${pageHeading('Create a code review','A focused brief. An exact revision. A clear handoff.')}<section class="panel form-panel"><div class="steps" aria-label="Review creation progress">${['Repository','Review scope','Confirm'].map((t,i)=>`<div class="step ${step>=i+1?'active':''}" ${step===i+1?'aria-current="step"':''}>0${i+1} · ${t}</div>`).join('')}</div><form data-form="review-wizard">${content}${err}<div class="form-actions">${A.btn(step===1?'Cancel':'Back',step===1?'cancel-review':'review-back','secondary')}<button class="btn primary" type="submit">${step===3?'Create demo review':'Continue'} ${A.icon('arrow')}</button></div></form></section>`;
  };
  function preserveWizard() { const f=document.querySelector('[data-form="review-wizard"]'); if(f) Object.assign(draft(),values(f)); }
  A.actions['review-back']=()=>{preserveWizard();c.reviewStep=Math.max(1,(c.reviewStep||1)-1);A.render();};
  A.actions['cancel-review']=()=>{c.reviewStep=1;c.reviewDraft=null;A.go('overview');};
  A.forms['review-wizard']=form=>{
    const d=draft(), step=c.reviewStep||1; Object.assign(d,values(form));
    if(step===1) {
      d.title=d.title.trim(); d.repo=normalizeRepo(d.repo); d.revision=d.revision.trim();
      if(!d.title) return fail('Please enter a review title.');
      if(!A.categories.some(category=>category.id===d.category)) return fail('Choose one of the listed task categories.');
      if(!validGithub(d.repo)) return fail('Enter a GitHub repository link in the form https://github.com/owner/repository.');
      if(d.revisionType==='commit'&&!/^[a-fA-F0-9]{7,40}$/.test(d.revision)) return fail('Enter a commit SHA with 7–40 hexadecimal characters.');
      if(d.revisionType==='pull-request'&&!/^[1-9][0-9]{0,7}$/.test(d.revision)) return fail('Enter a positive pull request number, such as 42.');
    }
    if(step===2) {
      if(!d.scope.trim()) return fail('Please describe the scope and acceptance criteria.');
      if(!Number.isInteger(Number(d.budget))||Number(d.budget)<1||Number(d.budget)>1000000) return fail('Enter a whole-dollar budget between $1 and $1,000,000.');
      if(!/^\d{4}-\d{2}-\d{2}$/.test(d.deadline)) return fail('Choose a preferred turnaround date.');
    }
    if(step<3){c.reviewStep=step+1;A.render();return;}
    const id='r-'+Date.now().toString(36), review={id,title:d.title,repo:d.repo,category:A.category(d.category).id,sha:d.revisionType==='commit'?d.revision:'PR #'+d.revision,revisionType:d.revisionType,revision:d.revision,stack:d.stack,scope:d.scope.trim(),budget:Number(d.budget),deadline:d.deadline,visibility:d.visibility,status:'Awaiting access',access:'pending',expertId:null,expertAccess:'pending',findings:[],proposals:[],messages:[]};
    A.state.reviews.unshift(review); A.state.activeReview=id; A.state.events.unshift({text:'Demo review created: '+d.title,time:'Just now',icon:'folder'}); A.persist(); c.reviewStep=1;c.reviewDraft=null; A.go('review'); A.toast('Demo review created. Repository access is pending.');
  };

  function verificationForm() {
    const d=c.applicationDraft||A.state.application||{};
    return `<form data-form="verification"><div class="form-grid">${field('Full name','name','required maxlength="100" autocomplete="name"',d.name||A.state.user.name||'')}${field('Contact email','email','required type="email" maxlength="254" autocomplete="email"',d.email||A.state.user.email||'')}${field('GitHub profile','github','required type="url" placeholder="https://github.com/your-handle"',d.github||'')}${select('Professional experience','experience',[['','Choose your experience'],['0–2 years','0–2 years'],['3–5 years','3–5 years'],['6–10 years','6–10 years'],['10+ years','10+ years']],d.experience||'')}${select('Primary specialty','specialty',[['','Choose your specialty'],['Application security','Application security'],['Backend & APIs','Backend & APIs'],['Frontend & accessibility','Frontend & accessibility'],['Infrastructure & reliability','Infrastructure & reliability'],['Testing & quality','Testing & quality']],d.specialty||'')}${field('Portfolio or work sample URL','portfolio','required type="url" placeholder="https://your-portfolio.example"',d.portfolio||'','Provide work you have permission to share. Private credentials are never required.')}${area('Tell us about your review experience','bio',d.bio||'','Include concrete examples of bugs found, systems improved, or code reviewed.')}<div class="field full"><label for="evidence">Optional supporting file (demo only)</label><input id="evidence" name="evidence" type="file" accept=".pdf,.txt,.md" data-input="evidence"><small>Only filename, size, and type are stored locally. The file is never uploaded or read. Use a sample document; maximum 5 MB.</small>${d.file?`<small>Selected: ${e(d.file.name)} · ${Math.ceil(d.file.size/1024)} KB</small>`:''}</div></div><div class="notice">${A.icon('shield')}<span>A separate verification team checks your profile, work evidence, and expertise. In this prototype, team decisions are simulations. Approval alone is not an audit of your identity.</span></div><label class="check-label"><input type="checkbox" name="consent" required>I confirm these details are accurate and agree to their review by the verification team.</label>${err}<div class="form-actions"><small>Decision status stays visible in your workspace.</small><button type="submit" class="btn primary">${A.state.application?.status==='changes_requested'?'Resubmit demo application':'Submit demo application'} ${A.icon('arrow')}</button></div></form>`;
  }
  A.views.verification=()=>{
    const app=A.state.application, status=app?.status;
    let content='';
    if(c.verificationEditing) content=verificationForm();
    else if(status==='pending')content=`<div class="empty">${A.icon('clock')}<h3>Your profile is in the demo queue</h3><p>The live service will route your application to a separate team. In this prototype you can explore the Team dashboard to simulate a decision.</p></div><div class="kv"><span>Applicant</span><strong>${e(app.name)}</strong></div><div class="kv"><span>Specialty</span><span>${e(app.specialty)}</span></div><div class="kv"><span>GitHub</span><span>${e(app.github)}</span></div><div class="form-actions">${A.btn('Edit application','edit-application','secondary')}${A.tag('Pending team review','amber')}</div>`;
    else if(status==='approved')content=`<div class="empty">${A.icon('shield')}<h3>Demo application approved</h3><p>Your local prototype profile can now submit proposals. Real verification will require an authenticated team review.</p></div><div class="form-actions">${A.btn('Update profile','edit-application','secondary')}${A.btn('Explore opportunities','navigate','primary','data-route="reviews"')}</div>`;
    else if(status==='rejected')content=`<div class="notice amber">${A.icon('file')}<span>Your demo application was declined.${app.notes?`<br>Team note: ${e(app.notes)}`:''} Update your evidence and submit again when ready.</span></div>${A.btn('Update and reapply','edit-application')}`;
    else content=`${status==='changes_requested'?`<div class="notice amber">${A.icon('message')}<span>Changes requested by the demo team: ${e(app.notes||'Please add more evidence of relevant experience.')}</span></div>`:''}${verificationForm()}`;
    return `${pageHeading('Coder verification','Show your expertise. Get reviewed. Find meaningful work.')}<section class="panel form-panel"><div class="section-title"><h2>${status==='pending'?'Application submitted':status==='approved'?'Your verified profile':'Build your reviewer profile'}</h2><p>Expertise and trust come first.</p></div>${content}</section>`;
  };
  A.inputs.evidence=(_,el)=>{
    const file=el.files?.[0]; if(!file) return;
    if(file.size>5*1024*1024||!/\.(pdf|txt|md)$/i.test(file.name)){el.value='';A.toast('Choose a PDF, TXT, or MD sample file no larger than 5 MB.');return;}
    const f=el.closest('form'); c.applicationDraft={...(c.applicationDraft||A.state.application||{}),...values(f),file:{name:file.name,size:file.size,type:file.type}};
    delete c.applicationDraft.evidence;
  };
  A.actions['edit-application']=()=>{c.applicationDraft={...A.state.application};c.verificationEditing=true;A.render();};
  A.forms.verification=form=>{
    const d=values(form); if(!d.name.trim()||!d.bio.trim())return fail('Please enter your name and review experience.');
    if(!validGithub(d.github.trim(),true))return fail('Enter a GitHub profile URL in the form https://github.com/username.');
    if(!d.experience||!d.specialty)return fail('Please choose your experience and specialty.');
    try{const u=new URL(d.portfolio);if(u.protocol!=='https:'||u.username||u.password)throw new Error();}catch{return fail('Use a valid HTTPS portfolio or work sample URL.');}
    const id=A.state.application?.id||'application-'+Date.now().toString(36);
    const file=form.querySelector('[name="evidence"]')?.files?.[0];
    if(file&&(file.size>5*1024*1024||!/\.(pdf|txt|md)$/i.test(file.name)))return fail('Choose a PDF, TXT, or MD sample file no larger than 5 MB.');
    const app={id,name:d.name.trim(),email:d.email.trim(),github:d.github.trim(),experience:d.experience,specialty:d.specialty,portfolio:d.portfolio.trim(),bio:d.bio.trim(),consent:true,status:'pending',notes:'',file:file?{name:file.name,size:file.size,type:file.type}:c.applicationDraft?.file||A.state.application?.file||null};
    A.state.application=app; const i=A.state.applications.findIndex(x=>x.id===id);if(i<0)A.state.applications.unshift({...app});else A.state.applications[i]={...app};
    A.state.events.unshift({text:'Demo coder verification submitted',time:'Just now',icon:'shield'});c.applicationDraft=null;c.verificationEditing=false;A.persist();A.render();A.toast('Application added to the local demo verification queue.');
  };
  function teamApplications(){const list=[...A.state.applications];if(A.state.application){const i=list.findIndex(x=>x.id===A.state.application.id);if(i<0)list.unshift(A.state.application);else list[i]=A.state.application;}return list;}
  A.views.team=()=>{
    const list=teamApplications(), filter=c.teamFilter||'all', shown=list.filter(x=>filter==='all'||x.status===filter);
    return `${pageHeading('Verification workspace','Help strong reviewers earn trust, one application at a time.')}<div class="notice amber">${A.icon('lock')}<span>Team workspace demonstration. All decisions are local simulations. The live team dashboard must require separate staff authorization.</span></div><div class="stats">${[['Applications',list.length],['Awaiting review',list.filter(x=>x.status==='pending').length],['Changes requested',list.filter(x=>x.status==='changes_requested').length],['Demo approvals',list.filter(x=>x.status==='approved').length]].map(([t,n])=>`<div class="stat"><div class="stat-top">${t}${A.icon('users')}</div><div class="stat-value">${n}</div><div class="stat-bottom">Local prototype queue</div></div>`).join('')}</div><section class="panel"><div class="panel-head"><div><h2>Reviewer applications</h2><p>Review evidence before making a decision.</p></div></div><div class="tabs">${[['all','All applications'],['pending','Pending'],['changes_requested','Changes requested'],['approved','Approved'],['rejected','Declined']].map(([v,t])=>`<button class="${filter===v?'active':''}" data-action="team-filter" data-filter="${v}">${t}</button>`).join('')}</div><div class="verification-list" style="padding:18px">${shown.length?shown.map(x=>`<article class="panel verification-item">${A.avatar(x.name.split(/\s+/).map(n=>n[0]).slice(0,2).join(''))}<div class="info"><h3>${e(x.name)}</h3><p>${e(x.specialty)} · ${e(x.experience)}</p><p>${e(x.github)}</p></div>${A.tag(({pending:'Pending review',changes_requested:'Changes requested',approved:'Demo approved',rejected:'Declined'})[x.status]||x.status,x.status==='approved'?'green':'amber')}${A.btn('Review profile','team-review','secondary',`data-id="${e(x.id)}"`)}</article>`).join(''):`<div class="empty">${A.icon('users')}<h3>No applications here yet</h3><p>Applications matching this status will appear here.</p></div>`}</div></section>`;
  };
  A.actions['team-filter']=el=>{c.teamFilter=el.dataset.filter;A.render();};
  A.actions['team-review']=el=>{
    const x=teamApplications().find(x=>x.id===el.dataset.id);if(!x)return; c.staffApplicationId=x.id;
    A.modal('Review '+x.name,'A team decision based on experience and evidence.',`<div class="kv"><span>Email</span><span>${e(x.email)}</span></div><div class="kv"><span>GitHub</span><span>${e(x.github)}</span></div><div class="kv"><span>Experience</span><span>${e(x.experience)}</span></div><div class="kv"><span>Specialty</span><span>${e(x.specialty)}</span></div><div class="kv"><span>Portfolio</span><span style="overflow-wrap:anywhere">${e(x.portfolio)}</span></div><h3 style="margin:18px 0 8px">Review experience</h3><p style="white-space:pre-wrap;overflow-wrap:anywhere">${e(x.bio)}</p>${x.file?`<div class="notice">${A.icon('file')}<span>Sample file metadata: ${e(x.file.name)} · ${Math.ceil(x.file.size/1024)} KB. File content is not available in this prototype.</span></div>`:''}<div class="notice amber">${A.icon('shield')}<span>Demonstration only. Verify evidence and account ownership through the live staff process before granting real reviewer permissions.</span></div><form data-form="team-decision">${select('Demo decision','decision',[['approved','Approve demo application'],['changes_requested','Request changes'],['rejected','Decline demo application']],x.status==='pending'?'approved':x.status)}${area('Decision note','notes',x.notes||'','Required for requests for changes or a decline.',false)}${err}<button class="btn primary" type="submit">Save demo decision</button></form>`,{large:true});
  };
  A.forms['team-decision']=form=>{
    const d=values(form);if(!['approved','changes_requested','rejected'].includes(d.decision))return fail('Choose a decision.');
    if(d.decision!=='approved'&&!d.notes.trim())return fail('Add a clear note explaining the requested changes or decline.');
    const id=c.staffApplicationId, entry=A.state.applications.find(x=>x.id===id); if(entry){entry.status=d.decision;entry.notes=d.notes.trim();}
    if(A.state.application?.id===id){A.state.application.status=d.decision;A.state.application.notes=d.notes.trim();}
    A.state.events.unshift({text:'Demo verification decision saved: '+d.decision.replace('_',' '),time:'Just now',icon:'shield'});A.persist();A.closeModal();A.render();A.toast('Local demo decision saved. No live permissions were changed.');
  };
  function activeReview(el){return A.state.reviews.find(r=>r.id===(el?.dataset.id||A.state.activeReview));}
  function accessModal(el,expert){
    const review=activeReview(el);if(!review)return A.toast('Select a review first.');
    const who=expert?A.state.experts.find(x=>x.id===review.expertId):null;
    if(expert&&!who)return A.toast('Select a doer before arranging their access.');
    c.accessReviewId=review.id;c.accessKind=expert?'expertAccess':'access';
    const email=expert?who.email:'antislop@bee3.in', status=review[c.accessKind];
    const verified=!!email;
    A.modal(expert?'Share access with your doer':'Arrange AI review access',expert?`Selected doer: ${who.name}`:'Access target: antislop@bee3.in',`<div class="notice amber">${A.icon('lock')}<span>This dashboard tracks your access handoff. It does not grant GitHub permissions or verify access. GitHub repository permissions require a GitHub integration or an owner action on GitHub.</span></div><div class="access-step"><span class="number">1</span><div><h4>Repository</h4><p style="overflow-wrap:anywhere">${e(review.repo)}</p><p>Revision: ${e(review.sha)}</p></div></div><div class="access-step"><span class="number">2</span><div><h4>${expert?'Doer access recipient':'Antislop access contact'}</h4><p>${verified?e(email):'Recipient not configured'}</p>${verified?A.btn('Copy email','flow-copy-email','secondary',`data-email="${e(email)}"`):''}<p style="margin-top:10px">${expert?'Confirm this account identity and grant only the repository access needed for the agreed scope. Sample expert emails in this prototype are illustrative.':'An email address alone is not a GitHub identity. The live onboarding will resolve the Antislop account or GitHub App and confirm installation permissions.'}</p></div></div><div class="access-step"><span class="number">3</span><div><h4>Track the access confirmation</h4><p>${status==='demo_confirmed'?'A local demo confirmation has been recorded. Real access remains unverified.':'Access is pending. No reviewer or AI has accessed the repository.'}</p></div></div><div class="form-actions">${A.btn('Close','close-modal','secondary')}${verified?A.btn('Simulate access confirmation','confirm-demo-access'):''}</div>`,{large:true});
  }
  A.actions['review-access']=el=>accessModal(el,false);
  A.actions['expert-access']=el=>accessModal(el,true);
  A.actions['flow-copy-email']=async el=>{try{await navigator.clipboard.writeText(el.dataset.email);A.toast('Email copied.');}catch{A.toast('Copy this email: '+el.dataset.email);}};
  A.actions['confirm-demo-access']=()=>{const r=A.state.reviews.find(x=>x.id===c.accessReviewId);if(!r)return; r[c.accessKind]='demo_confirmed';A.state.events.unshift({text:`Demo ${c.accessKind==='access'?'AI':'doer'} access acknowledged for ${r.title}`,time:'Just now',icon:'lock'});A.persist();A.closeModal();A.render();A.toast('Demo acknowledgement saved. Actual GitHub access has not been verified.');};
})();
